const u=t=>String(t).padStart(2,"0");function i(t){if(!t)return"—";const n=new Date(t);return Number.isNaN(n.getTime())||n.getFullYear()<2e3?"—":`${u(n.getHours())}:${u(n.getMinutes())}:${u(n.getSeconds())}`}function o(t){if(!t)return"—";const n=new Date(t);if(Number.isNaN(n.getTime())||n.getFullYear()<2e3)return"—";const r=Math.round((Date.now()-n.getTime())/1e3);return r<5?"刚刚":r<60?`${r} 秒前`:r<3600?`${Math.floor(r/60)} 分钟前`:r<86400?`${Math.floor(r/3600)} 小时前`:`${Math.floor(r/86400)} 天前`}function f(t){if(t==null||t<=0)return"0:00";const n=Math.floor(t/3600),r=Math.floor(t%3600/60),e=Math.floor(t%60);return n>0?`${n}:${u(r)}:${u(e)}`:`${r}:${u(e)}`}function a(t){if(!t||t<=0)return"0 秒";const n=Math.floor(t/3600),r=Math.round(t%3600/60);if(n>0)return r>0?`${n} 小时 ${r} 分`:`${n} 小时`;const e=Math.floor(t%60);return r>0?e>0?`${r} 分 ${e} 秒`:`${r} 分`:`${e} 秒`}function c(t){return t?t<1e3?`${Math.round(t)}ms`:`${(t/1e3).toFixed(1)}s`:"—"}function l(t){return t==null?"—":t.toLocaleString("zh-CN")}function d(t){return t===0?"免费":t<.01?t.toFixed(4):t.toFixed(2)}function $(t){return t<0?"—":t>=1e3?`${(t/1e3).toFixed(1)}k`:String(t)}function s(t){return t>=200&&t<300?"ok":t>=400&&t<500?"warn":t>=500?"bad":""}function h(t){return t?t.includes("6004")?"当日模型用量用尽":t.includes("429")?"上游限流":t.includes("404")?"上游路径偶发缺失":t.includes("余额")?"积分耗尽":t.includes("12153")?"凭证失效":t:"限流冷却"}export{f as a,h as b,i as c,a as d,o as e,d as f,c as m,l as n,s,$ as t};
